export function silhouette(broad=false){const c=document.createElement('canvas');c.width=256;c.height=512;const x=c.getContext('2d');x.fillStyle='#554b35';x.fillRect(123,240,10,270);if(broad){for(let i=0;i<330;i++){const a=hash(i,1)*TAU,r=Math.sqrt(hash(i,5)),xx=128+Math.cos(a)*r*107,yy=160+Math.sin(a)*r*127;x.fillStyle=['#355d43','#42694a','#4d7852','#5b8458','#719565'][i%5];x.beginPath();x.ellipse(xx,yy,10+hash(i,8)*17,9+hash(i,10)*17,0,0,TAU);x.fill();}}else for(let k=0;k<27;k++){const y=32+k*14,width=9+k*3.7;for(let j=0;j<32;j++){const xx=128+(hash(j,k)-.5)*width*2,yy=y+hash(k,j)*35;x.strokeStyle=['#244e40','#315d48','#426d4d','#557957'][j%4];x.lineWidth=2+hash(k,j)*4;x.beginPath();x.moveTo(128,y-20);x.lineTo(xx,yy);x.stroke();}}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
export function crossTree(){const parts=[];for(let i=0;i<2;i++){const p=new T.PlaneGeometry(1,1);p.translate(0,.5,0);p.rotateY(i*Math.PI/2);parts.push(p);}return join(parts);}
