 setTravelMode(state,player){const airborne=!!state.flying&&player.y-this.geo.height(player.x,player.z)>90,travel=state.horizontalSpeed>35||!!state.flying;if(travel!==this.travel||airborne!==this.airborne)this.modeChanged=true;this.travel=travel;this.airborne=airborne;for(const b of[...this.batches.values(),...this.rocks,...this.shrubs,...this.flowers])b.group.visible=!airborne;for(const m of[this.grass,this.leaves,this.detailTrunks])m.visible=!airborne;if(airborne){this.farCut.value=0;for(const p of this.plants)p.group.visible=false;}}
 refresh(player,force=false){this.observer.value.copy(player);if(this.airborne)return;if(this.modeChanged){force=true;this.modeChanged=false;}if(!force&&Math.hypot(player.x-this.last.x,player.z-this.last.z)<32)return;this.last.copy(player);this.ecoCache.clear();const low=this.quality==='low';this.farCut.value=this.travel?110:low?215:300;const radius=low?235:325,step=low?17:12,cx=Math.floor(player.x/step)*step,cz=Math.floor(player.z/step)*step,rows=new Map([...this.batches.keys()].map(k=>[k,[]])),rocks=this.rocks.map(()=>[]),shrubs=this.shrubs.map(()=>[]),flowers=this.flowers.map(()=>[]),nearTrees=[];this.treeColliders=[];this.rockColliders=[];this.treeIndex=null;this.rockIndex=null;
  for(let z=cz-radius;z<=cz+radius;z+=step)for(let x=cx-radius;x<=cx+radius;x+=step){const xx=x+(hash(x,z,7)-.5)*step*.85,zz=z+(hash(x,z,8)-.5)*step*.85,d=Math.hypot(xx-player.x,zz-player.z);if(d>radius||xx<-10000||xx>10000||zz<-8000||zz>8000)continue;const e=this.eco(xx,zz),r=hash(x,z,15),y=this.geo.height(xx,zz);let treeHere=false;if(r<e.tree*.9&&this.allowed(xx,zz,4)){const species=this.geo.speciesAt(xx,zz,hash(x,z,24)),height=(species==='birch'?13:species==='broadleaf'?14:species==='pine-small'?8:species==='juniper'?1.3:19)*(.72+hash(x,z,19)*.5)*(.48+.52*smooth(0,260,e.forestLine-e.altitude));const p={x:xx,z:zz,y,height,angle:hash(x,z,4)*TAU,wide:.8+hash(x,z,6)*.4,d};rows.get(species).push(p);treeHere=true;if(d<90&&height>5)nearTrees.push(p);if(d<(this.travel?radius:65))this.treeColliders.push({x:xx,z:zz,r:Math.max(.18,height*.019)});}
   if(!treeHere&&d<150&&e.up>.4&&hash(x,z,118)<(e.altitude>e.meadowLine?.62:.13)&&this.allowed(xx,zz,1.5)){const index=Math.floor(hash(x,z,82)*rocks.length),p={x:xx,y:y-.15,z:zz,height:.4+hash(x,z,84)*(e.altitude>3700?3.7:2.2),angle:r*TAU,wide:.7+hash(x,z,8)*.8,tiltX:(hash(x,z,33)-.5)*.2,tiltZ:(hash(x,z,34)-.5)*.2};rocks[index].push(p);const t=this.assets.template(['rock_largeA','rock_largeB','rock_smallA','rock_smallB','rock_tallC'][index]),scale=p.height/t.height;this.rockColliders.push({x:xx,z:zz,y:y-.15,top:y-.15+p.height,hx:Math.max(.12,t.width*scale*p.wide*.42),hz:Math.max(.12,t.depth*scale*p.wide*.42),angle:p.angle});}
   if(d<130&&e.shrub>.08&&r<e.shrub*.8&&this.allowed(xx,zz,2.5))shrubs[Math.floor(hash(x,z,92)*shrubs.length)].push({x:xx,y,z:zz,height:.3+hash(x,z,41)*(e.altitude>3300?.55:1.1),angle:r*TAU});
  }
  for(const [species,list]of rows){list.sort((a,b)=>a.d-b.d);this.batches.get(species).set(this.travel?list.filter(p=>p.d<150):list);}this.rocks.forEach((b,i)=>b.set(rocks[i]));this.shrubs.forEach((b,i)=>b.set(shrubs[i]));
  let n=0,flowerCount=0;const cap=this.travel?1800:low?10000:21000,cell=30,px=Math.floor(player.x/cell)*cell,pz=Math.floor(player.z/cell)*cell;for(let i=0;i<cap*3&&n<cap;i++){const a=hash(i,px,3)*TAU,r=Math.sqrt(hash(i,pz,9))*76,x=px+Math.sin(a)*r,z=pz+Math.cos(a)*r,e=this.eco(x,z);if(e.grass<.04||hash(i,px,61)>e.grass*.9||!this.allowed(x,z,1.7)||this.geo.height(x,z)+ALT_BASE>e.meadowLine||e.grade>1)continue;const h=(.55+hash(i,pz,66)*.75)*(e.altitude>3300?.7:1);dummy.position.set(x,this.geo.height(x,z)-.025,z);dummy.rotation.set(0,a,0);dummy.scale.set(h,h,h);dummy.updateMatrix();this.grass.setMatrixAt(n,dummy.matrix);this.grass.setColorAt(n,color.set(['#6d9744','#85a74e','#799d43','#a0b46a','#5d8544'][i%5]).multiplyScalar(.9+hash(i,px,77)*.2));n++;
   if(i%15===0&&flowerCount<950&&e.altitude<e.meadowLine-30&&this.season!==3){const type=e.altitude>3300?(i%2?0:3):e.moisture>.58?i%2:i%5;flowers[type].push({x,y:this.geo.height(x,z),z,height:.22+hash(i,pz,74)*.4,angle:a});flowerCount++;}}
  this.grass.count=n;this.grass.instanceMatrix.needsUpdate=true;if(this.grass.instanceColor)this.grass.instanceColor.needsUpdate=true;this.flowers.forEach((b,i)=>b.set(flowers[i]));this.addDetails(this.travel?[]:nearTrees);this.refreshPlants(player);this.treeIndex=new Spatial(12);for(const p of this.treeColliders)this.treeIndex.add(p,[p.x-p.r-.4,p.z-p.r-.4,p.x+p.r+.4,p.z+p.r+.4]);this.rockIndex=new Spatial(12);for(const p of this.rockColliders){const r=p.hx+p.hz+.5;this.rockIndex.add(p,[p.x-r,p.z-r,p.x+r,p.z+r]);}}
 addDetails(trees){let n=0,trunks=0;for(const tree of trees.slice(0,130)){if(trunks<170){dummy.position.set(tree.x,tree.y+tree.height*.27,tree.z);dummy.rotation.set(0,tree.angle,0);dummy.scale.set(tree.height*.06,tree.height*.54,tree.height*.06);dummy.updateMatrix();this.detailTrunks.setMatrixAt(trunks++,dummy.matrix);}for(let j=0;j<26&&n<4500;j++){const a=j*2.399+tree.angle,u=.25+hash(j,tree.x,30)*.66,r=tree.height*.19*(1-Math.abs(u-.68)*1.2),x=tree.x+Math.sin(a)*r,z=tree.z+Math.cos(a)*r;dummy.position.set(x,tree.y+tree.height*u,z);dummy.rotation.set((hash(j,tree.z,4)-.5)*1.8,a,hash(j,tree.x,5)*TAU);const s=tree.height*.11;dummy.scale.set(s,s,1);dummy.updateMatrix();this.leaves.setMatrixAt(n,dummy.matrix);this.leaves.setColorAt(n,color.set(['#5e8e47','#74a458','#8bb35c','#648b45'][j%4]));n++;}}
  this.leaves.count=n;this.leaves.instanceMatrix.needsUpdate=true;if(this.leaves.instanceColor)this.leaves.instanceColor.needsUpdate=true;this.detailTrunks.count=trunks;this.detailTrunks.instanceMatrix.needsUpdate=true;}
 refreshPlants(player){for(const p of this.plants)this.scene.remove(p.group);this.plants=[];const x0=Math.floor(player.x/40)*40,z0=Math.floor(player.z/40)*40;for(let i=0;i<45&&this.plants.length<18;i++){const a=hash(i,x0,4)*TAU,r=7+hash(i,z0,7)*40,x=x0+Math.sin(a)*r,z=z0+Math.cos(a)*r,e=this.eco(x,z);if(e.grass+e.shrub<.1||!this.allowed(x,z,.8)||e.altitude>e.meadowLine||e.grade>.7)continue;const type=e.altitude>3300?3:e.forest&&e.moisture>.5?2:i%2,name=['grass_leafs','flower_purpleB','flower_redA','flower_yellowB'][type],group=this.assets.models.get(name).scene.clone(true),box=new T.Box3().setFromObject(group),h=box.max.y-box.min.y;group.scale.setScalar((type===0?.65:.5)/h);group.position.set(x,this.geo.height(x,z),z);group.rotation.y=a;const id=Math.round(x)+':'+Math.round(z)+':'+type;this.scene.add(group);this.plants.push({group,x,z,type,id,collectedAt:this.collected.get(id)||-1000});}}
